const contexts=[];for(const scaleName of ['Major','  Natural   Minor ','DORIAN','',null,'\u0085Major\u0085'])for(const rootNote of [0,11,null,12])for(const type of ['chord-progression','bassline'])contexts.push({spec:{type,params:type==='chord-progression'?{numerals:['I','IV','V']}:{chords:['i','iv','v']}},input:{...pure[1],scale:{rootNote,scaleName,scaleMode:true,scaleIntervals:[]}}});
