const host=new McpHost(adapter),results=[],states=[];const args=params(spec,scope);const preview=await host.liveMidiTransformPreviewAsync(1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
