const created=scope==='duplicate'?sim.state.tracks.flatMap(t=>t.clips).find(c=>c.ref===record.created?.ref):sim.state.tracks[0].clips[0];if(created&&scenario==='undo-other-identity')created.objectIdentity='other';if(created&&scenario==='undo-other-content')created.notes[0].velocity=51;if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
